#!/usr/bin/env python3
"""Emit a kernel-checked convolution certificate for the target-sum code."""
import argparse
from pathlib import Path

RADIX, CHAINS, TARGET_SUM = 16, 32, 330
# Complement each digit: words with sum 330 correspond to words with sum 150.
COUNTED_SUM = CHAINS * (RADIX - 1) - TARGET_SUM
DESTINATION = Path(__file__).resolve().parents[1] / 'Xmss/Proof/TargetSum/EncodingCardinalityCertificate.lean'


def generate():
    lines = [
        'import Xmss.Proof.TargetSum.EncodingCardinality',
        'import Xmss.Proof.TargetSum.Code', '',
        '/-! Generated by scripts/generate_encoding_count.py.',
        'Each row equation is checked by the kernel, without native_decide. -/', '',
        'set_option maxRecDepth 2000', 'set_option maxHeartbeats 2000000', '',
        'namespace Xmss.TargetSum', '',
    ]
    row = [1] + [0] * COUNTED_SUM
    for length in range(CHAINS + 1):
        if length:
            row = [sum(row[total - digit] for digit in range(RADIX) if digit <= total)
                   for total in range(COUNTED_SUM + 1)]
        last = min((RADIX - 1) * length, COUNTED_SUM)
        lines += [f'private def row{length} : List ℕ := [']
        values = row[:last + 1]
        for start in range(0, len(values), 8):
            lines.append('  ' + ', '.join(map(str, values[start:start + 8])) +
                         (',' if start + 8 < len(values) else ']' +
                          (f' ++ List.replicate {COUNTED_SUM - last} 0' if last < COUNTED_SUM else '')))
        lines += ['', f'private theorem row{length}_eq : countRow {RADIX} {COUNTED_SUM} {length} = row{length} := by']
        if length:
            lines.append(f'  rw [countRow, row{length - 1}_eq]')
        lines += ['  decide +kernel', '']
    lines += [
        '/-- The exact number of 32-digit radix-sixteen words with sum 330. -/',
        'theorem wordCount_sixteen_thirtyTwo_330 :',
        f'    wordCount {RADIX} {CHAINS} {TARGET_SUM} = {row[COUNTED_SUM]} := by',
        '  rw [wordCount_complement_330]',
        f'  rw [← countRow_getD_eq_wordCount {RADIX} {COUNTED_SUM} {CHAINS} {COUNTED_SUM} le_rfl, row{CHAINS}_eq]',
        '  decide +kernel', '', 'end Xmss.TargetSum', '',
    ]
    return '\n'.join(lines)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true',
                        help='check the existing certificate without changing it')
    args = parser.parse_args()
    certificate = generate()
    if args.check:
        if not DESTINATION.is_file() or DESTINATION.read_text() != certificate:
            parser.exit(1, 'Encoding certificate is out of date; run scripts/generate_encoding_count.py.\n')
        print('OK: the target-sum encoding certificate reproduces exactly.')
    else:
        DESTINATION.write_text(certificate)
